def decode_bg(blob, palette):
    """RLE+base64 blob -> (142,160,3) uint8 image."""
    raw = base64.b64decode(blob)
    flat = np.zeros(142 * 160, np.uint8)
    pos = 0
    for i in range(0, len(raw), 2):
        v, ln = raw[i], raw[i + 1]
        flat[pos:pos + ln] = v
        pos += ln
    idx = flat.reshape(142, 160)
    return np.array(palette, np.uint8)[idx]


